"""Rewrite every phrase as a sequence of blind texts (rule P7, run 2026-11-09T0228Z). Each clause used was checked by
the main session against the definition's Lean body; clauses whose plain-words parse is ambiguous (e.g. "redshift over
one plus redshift", "sine of root K χ over root K") were left out."""
import re, sys
P = "scripts/trust/phrases.txt"
NEW = {
"Checked.Cosmography.hubble": "the Hubble rate of the scale factor {a} at the cosmic time of evaluation {t} (logarithmic derivative of the scale factor with respect to cosmic time; positive for expansion and negative for contraction)",
"Checked.Cosmography.decel": "the deceleration parameter of the scale factor {a} at the cosmic time of evaluation {t} (minus acceleration times scale factor over velocity squared; negative value means accelerating expansion)",
"Checked.Cosmography.redshift": "the cosmological redshift at the observation time {t₀} for the emission time {t} with the scale factor {a} (one plus redshift is the scale factor at observation over that at emission; positive when emission precedes observation in an expanding universe; negative redshift is blueshift)",
"BambaK.lumDist": "the luminosity distance in FLRW with curvature at the observation time {t₀} for the emission time {t} with the scale factor {a} and the spatial curvature constant {K} (units in which the speed of light is one; positive curvature constant means closed, negative means open)",
"BambaA.angDist": "the angular diameter distance in FLRW with curvature at the observation time {t₀} for the emission time {t} with the scale factor {a} and the spatial curvature constant {K} (scale factor at emission times the transverse distance of the comoving distance; positive curvature constant means closed, negative means open)",
"Aviles.IsFlatLCDM": "the scale factor {a} obeys the flat ΛCDM Friedmann expansion law with the present matter density parameter {Ω} at the observation time {t₀} (spatially flat universe with dust and a cosmological constant; holds on a whole neighbourhood of {t₀}; present Hubble rate is positive so the universe is expanding)",
"Aviles.cosmoCoeff": "the cosmographic coefficient of the scale factor {a} at the time of evaluation {t} for the derivative order of the coefficient {n} ({n}-th time derivative of the scale factor over the scale factor divided by the {n}-th power of the Hubble rate; order 2 coefficient is minus the deceleration parameter; order 3 coefficient is the jerk; orders 0 and 1 coefficients are one)",
"BambaY.yred": "the y redshift at the observation time {t₀} for the emission time {t} with the scale factor {a} (one minus the scale factor at emission over that at observation; positive for redshift, negative for blueshift)",
"BambaK.omega0": "the present total density parameter Ω₀ at the observation time {t₀} for the spatial curvature constant {K} and the scale factor {a} (total density parameter and not the matter fraction alone; one plus curvature term, positive curvature constant gives above one; equals one for zero curvature)",
"BambaZ.curvK": "the dimensionless spatial curvature parameter at the observation time {t₀} for the spatial curvature constant {K} and the scale factor {a} (has sign of curvature constant, minus the curvature density parameter; total density parameter minus one; positive for closed and negative for open)",
"BambaY.lumDistFlat": "the luminosity distance in flat FLRW at the observation time {t₀} for the emission time {t} with the scale factor {a} (luminosity distance for zero spatial curvature; units in which the speed of light is one)",
"BambaY.comoving": "the comoving radial distance for the emission time {t} and the observation time {t₀} with the scale factor {a} (integral of one over the scale factor over cosmic time; integrated from emission time to observation time; units in which the speed of light is one)",
"CPL.IsFlatCPL": "the scale factor {a} obeys the flat matter plus CPL dark energy Friedmann expansion law with the present matter density parameter {Ω}, the present dark energy equation of state {w₀} and the equation of state evolution parameter {wₐ} at the observation time {t₀} (spatially flat universe with dust and separately conserved dark energy; redshift z is measured from {t₀}; holds on a whole neighbourhood of {t₀}; present Hubble rate is positive so the universe is expanding)",
"FRCosmo.curv": "the Ricci scalar of flat FLRW with the scale factor {a} at the cosmic time of evaluation {t} (negative convention, de Sitter has negative Ricci scalar; negative convention so de Sitter has minus twelve times Hubble rate squared)",
"FRCosmo.rhoM": "the dust matter density at the time of evaluation {t} for the present matter density parameter {Ω} and the present time {t₀} with the scale factor {a} (pressureless dust density in units where kappa squared is one; falls as the inverse cube of the scale factor; critical density is three times present Hubble rate squared; Ω is relative to the general relativity critical density)",
"FRCosmo.FriedmannEq": "the metric F(R) gravity Friedmann equation with dust holds at the time of evaluation {t} for the present matter density parameter {Ω}, the scale factor {a}, the gravity Lagrangian function of Ricci scalar {F} and the present time {t₀} (constraint equation of metric F of R gravity in flat FLRW; dust source and kappa squared is one; negative Ricci scalar convention, minus the common one; multiplied through by F prime with no division; derivatives of F are taken with respect to R)",
"FRCosmo.MasterEq": "the metric F(R) gravity second equation with dust holds at the time of evaluation {t} for the present matter density parameter {Ω}, the scale factor {a}, the gravity Lagrangian function of Ricci scalar {F} and the present time {t₀} (Hubble rate derivative equation of metric F of R gravity; flat FLRW with dust source and kappa squared is one; negative Ricci scalar convention, minus the common one; multiplied through by minus two F prime with no division)",
"Transverse.transverse": "the FLRW transverse distance function for the spatial curvature constant {K} at the comoving radial distance {χ} (second derivative in {χ} is minus {K} times itself; vanishes at zero with unit slope; positive curvature constant gives sine, closed spherical case; equals {χ} itself for zero {K})",
"CubicEOS.IsCriticalIsotherm": "the isotherm pressure function of molar volume {p} satisfies the critical point condition of an isotherm at the molar volume at the point {v} (first and second volume derivatives of pressure both vanish; a mere stationary point is not critical)",
"Coexistence.IsMaxwellCoexistence": "the isotherm pressure function of molar volume {p} satisfies the Maxwell equal area coexistence condition with the liquid molar volume {vl}, the gas molar volume {vg} and the saturation pressure {ps} (liquid volume is less than gas volume; pressure equals the saturation pressure at both volumes; equal areas between the isotherm and the saturation pressure line)",
"Duffing.IsDuffingSolution": "the position as function of time {x} is a Duffing oscillator initial value problem solution with the linear stiffness coefficient {k}, the cubic stiffness coefficient {β}, the initial position {x₀}, the initial velocity {v₀} and the final time of the interval {T} (the second derivative plus {k} times {x} plus {β} times {x} cubed vanishes; holds on the closed time interval from zero to {T}; derivatives at the endpoints are one-sided; restoring force for positive stiffness, acceleration equals minus force terms)",
"MichaelisMenten.IsMMSolution": "the substrate concentration over time {s}, the free enzyme concentration over time {e}, the complex concentration over time {c} and the product concentration over time {p} are a Michaelis Menten mass action initial value problem solution with the binding rate constant {k₁}, the unbinding rate constant {km₁}, the catalytic rate constant {k₂}, the initial substrate concentration {s₀}, the initial free enzyme concentration {e₀}, the initial complex concentration {c₀}, the initial product concentration {p₀} and the final time of the interval {T} (mass action kinetics of E plus S reversibly forming complex C; {k₁} is the rate constant of E plus S forming C; {km₁} is the rate constant of C returning to E plus S; {k₂} is the rate constant of C forming E plus P; holds on the closed time interval from zero to {T}; binding consumes substrate and free enzyme, forms complex)",
"Robertson.IsRobSolution": "the concentration of species A over time {y₁}, the concentration of species B over time {y₂} and the concentration of species C over time {y₃} are a Robertson chemical kinetics initial value problem solution with the rate constant of the first reaction {k₁}, the rate constant of the second reaction {k₂}, the rate constant of the third reaction {k₃}, the initial concentration of species A {a₀}, the initial concentration of species B {b₀}, the initial concentration of species C {c₀} and the final time of the interval {T} (mass action kinetics of the Robertson network; A converts to B with rate constant {k₁}; B plus C gives A plus C with rate constant {k₂}; two B give B plus C with rate constant {k₃}; holds on the closed time interval from zero to {T})",
}
lines = open(P, encoding="utf-8").read().splitlines()
out, seen = [], set()
for l in lines:
    if l.strip() and not l.startswith("#") and " | " in l:
        d = l.split(" | ", 1)[0].strip()
        assert d in NEW, d
        seen.add(d)
        out.append(f"{d} | {NEW[d]}")
    else:
        out.append(l)
assert seen == set(NEW), set(NEW) - seen
open(P, "w", encoding="utf-8").write("\n".join(out) + "\n")
